CREATE MATERIALIZED VIEW non_leaf_1212 AS
SELECT mi1.id AS mi1_id, mi1.movie_id AS mi1_movie_id, mi1.info_type_id AS mi1_info_type_id, mi1.info AS mi1_info, mi1.note AS mi1_note, n.id AS n_id, n.name AS n_name, n.imdb_index AS n_imdb_index, n.imdb_id AS n_imdb_id, n.gender AS n_gender, n.name_pcode_cf AS n_name_pcode_cf, n.name_pcode_nf AS n_name_pcode_nf, n.surname_pcode AS n_surname_pcode, n.md5sum AS n_md5sum, it2.id AS it2_id, it2.info AS it2_info, cn.id AS cn_id, cn.name AS cn_name, cn.country_code AS cn_country_code, cn.imdb_id AS cn_imdb_id, cn.name_pcode_nf AS cn_name_pcode_nf, cn.md5sum AS cn_md5sum, ct.id AS ct_id, ct.kind AS ct_kind, mc.id AS mc_id, mc.movie_id AS mc_movie_id, mc.company_id AS mc_company_id, mc.company_type_id AS mc_company_type_id, mc.note AS mc_note, t.id AS t_id, t.title AS t_title, t.imdb_index AS t_imdb_index, t.kind_id AS t_kind_id, t.production_year AS t_production_year, t.imdb_id AS t_imdb_id, t.phonetic_code AS t_phonetic_code, t.episode_of_id AS t_episode_of_id, t.season_nr AS t_season_nr, t.episode_nr AS t_episode_nr, t.series_years AS t_series_years, t.md5sum AS t_md5sum, ci.id AS ci_id, ci.person_id AS ci_person_id, ci.movie_id AS ci_movie_id, ci.person_role_id AS ci_person_role_id, ci.note AS ci_note, ci.nr_order AS ci_nr_order, ci.role_id AS ci_role_id, rt.id AS rt_id, rt.role AS rt_role, pi.id AS pi_id, pi.person_id AS pi_person_id, pi.info_type_id AS pi_info_type_id, pi.info AS pi_info, pi.note AS pi_note, kt.id AS kt_id, kt.kind AS kt_kind
FROM movie_info AS mi1, name AS n, info_type AS it2, company_name AS cn, company_type AS ct, movie_companies AS mc, title AS t, cast_info AS ci, role_type AS rt, person_info AS pi, kind_type AS kt
WHERE mi1.movie_id = t.id AND mi1.info ~~* '%d%' AND mi1.info_type_id = 3 AND n.id = ci.person_id AND it2.id = 38 AND cn.id = mc.company_id AND ct.id = mc.company_type_id AND mc.movie_id = t.id AND t.id = ci.movie_id AND t.production_year <= 2015 AND t.production_year >= 1875 AND ci.person_id = pi.person_id AND ci.role_id = rt.id AND rt.role IN ('composer', 'costume designer', 'director', 'miscellaneous crew') AND pi.info ~~* '%che%' AND pi.info_type_id = 38 AND kt.id = t.kind_id AND kt.kind IN ('episode', 'movie', 'tv mini series', 'tv series', 'video game', 'video movie');